using UnityEngine;

namespace GoodCopBadCop.FilmStudio
{
    /// <summary>
    /// Point of interest inside a <see cref="StudioSet"/>: a prop, opening or surface the director can stage against
    /// (insert shots via camera.targetId, foreground framing via camera.foregroundId, face actions).
    /// Generated by StudioSetAnalyzer from Main.unity object names; the description can be edited by hand.
    /// </summary>
    public class StudioPoint : MonoBehaviour
    {
        public string pointId;
        /// <summary>prop | opening | surface | screen | sign</summary>
        public string kind = "prop";
        [TextArea(1, 3)] public string description;
        [Tooltip("Approximate radius of the object in metres (drives insert-shot size).")]
        public float radius = 0.25f;
        [Tooltip("Lets cameras look through it (glass, windows). Openings only.")]
        public bool seeThrough;

        private void OnDrawGizmos()
        {
            Gizmos.color = seeThrough ? new Color(0.3f, 0.8f, 1f, 0.8f) : new Color(0.4f, 1f, 0.5f, 0.8f);
            Gizmos.DrawWireSphere(transform.position, Mathf.Max(0.05f, radius));
        }
    }
}
